CREATE DATABASE IF NOT EXISTS fittrack;
USE fittrack;
CREATE TABLE IF NOT EXISTS members (id BIGINT AUTO_INCREMENT PRIMARY KEY,name VARCHAR(120) NOT NULL,email VARCHAR(190) NOT NULL UNIQUE,password_hash VARCHAR(255) NOT NULL,phone VARCHAR(30),date_of_birth DATE,role ENUM('admin','trainer','member') NOT NULL DEFAULT 'member',status ENUM('active','inactive','suspended') NOT NULL DEFAULT 'active',created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS trainers (id BIGINT AUTO_INCREMENT PRIMARY KEY,name VARCHAR(120) NOT NULL,email VARCHAR(190) NOT NULL UNIQUE,phone VARCHAR(30),specialty VARCHAR(120),hire_date DATE,status ENUM('active','inactive') NOT NULL DEFAULT 'active',created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS membership_plans (id BIGINT AUTO_INCREMENT PRIMARY KEY,name VARCHAR(100) NOT NULL UNIQUE,duration_days INT NOT NULL,price DECIMAL(10,2) NOT NULL,description TEXT,status ENUM('active','inactive') NOT NULL DEFAULT 'active',created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,CHECK(duration_days>0),CHECK(price>=0)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS memberships (id BIGINT AUTO_INCREMENT PRIMARY KEY,member_id BIGINT NOT NULL,plan_id BIGINT NOT NULL,start_date DATE NOT NULL,end_date DATE NOT NULL,status ENUM('active','expired','cancelled','pending') NOT NULL DEFAULT 'pending',created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(member_id) REFERENCES members(id),FOREIGN KEY(plan_id) REFERENCES membership_plans(id),INDEX idx_memberships_member(member_id),INDEX idx_memberships_status_end(status,end_date),CHECK(end_date>=start_date)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS payments (id BIGINT AUTO_INCREMENT PRIMARY KEY,member_id BIGINT NOT NULL,membership_id BIGINT,amount DECIMAL(10,2) NOT NULL,payment_method VARCHAR(40) NOT NULL,reference_code VARCHAR(120) UNIQUE,status ENUM('pending','paid','failed','refunded') NOT NULL DEFAULT 'pending',paid_at DATETIME,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(member_id) REFERENCES members(id),FOREIGN KEY(membership_id) REFERENCES memberships(id),INDEX idx_payments_member(member_id),CHECK(amount>=0)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS fitness_classes (id BIGINT AUTO_INCREMENT PRIMARY KEY,title VARCHAR(120) NOT NULL,description TEXT,trainer_id BIGINT,starts_at DATETIME NOT NULL,capacity INT NOT NULL DEFAULT 20,status ENUM('scheduled','cancelled','completed') NOT NULL DEFAULT 'scheduled',created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(trainer_id) REFERENCES trainers(id),CHECK(capacity>0),INDEX idx_classes_starts(starts_at)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS class_assignments (id BIGINT AUTO_INCREMENT PRIMARY KEY,class_id BIGINT NOT NULL,member_id BIGINT NOT NULL,status ENUM('booked','attended','cancelled') NOT NULL DEFAULT 'booked',booked_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(class_id) REFERENCES fitness_classes(id) ON DELETE CASCADE,FOREIGN KEY(member_id) REFERENCES members(id) ON DELETE CASCADE,UNIQUE KEY uq_class_member(class_id,member_id),INDEX idx_assignments_member(member_id)) ENGINE=InnoDB;
